        figmaEmbed: "https://embed.figma.com/proto/FLob460o8DWzCK0HrIhopz/Minimum-Viable-Product?node-id=1-6&scaling=scale-down&content-scaling=fixed&page-id=0%3A1&starting-point-node-id=1%3A5&embed-host=share",
